// Conversions between related types (arithmetic, inheritance)
double d_val = 5.75;
int i_val = static_cast<int>(d_val); // i_val == 5

class Base {};
class Derived : public Base {};
Derived* d_ptr = new Derived;
Base* b_ptr = static_cast<Base*>(d_ptr);


// Runtime-checked polymorphic conversion
class VBase { public: virtual ~VBase() = default; };
class VDerived : public VBase {};

VBase* vb = new VDerived;
// Safe downcast; returns nullptr on failure
VDerived* vd = dynamic_cast<VDerived*>(vb);


// Removing constness (use sparingly)
const int CONST_VAL = 100;

// Modify a pointer to const data
int* mutable_ptr = const_cast<int*>(&CONST_VAL);
// mutable_ptr[0] = 50; // Undefined Behavior if CONST_VAL was immutable


// Dangerous, low-level bitwise conversion
int i_data = 0xDEADBEEF;
int* i_ptr = &i_data;

// Treat memory address as a different type
char* c_ptr = reinterpret_cast<char*>(i_ptr);
long l_addr = reinterpret_cast<long>(i_ptr);
